/* ============================================================
   أطياب الجاسم (React) — أنيميشن «طيران البطاقة» (R9)

   عند «أضف للعربة»: صورة المنتج تطير من البطاقة إلى أيقونة
   العربة — لتوحي بأنها دخلت العربة فعلاً.
   وعند المفضلة: نفس الطيران نحو أيقونة القلب — بلا أي عدّاد.

   · Web Animations API فقط — بلا مكتبات، وبلا تغيير منطق Redux.
   · تُستدعى لحظة النقر (قبل إعادة الرسم) فتُقرأ الإحداثيات فورًا.
   · تحترم تقليل الحركة (prefers-reduced-motion) — نبض فقط بلا طيران.
   · آمنة: أي خطأ DOM يُبتلع بصمت ولا يمنع الإضافة/التنبيه.
   ============================================================ */

function rectOf(el) {
  try {
    if (!el || !el.getBoundingClientRect) return null;
    const r = el.getBoundingClientRect();
    /* display:none → بلا تخطيط (الجوال مغلق/سطح المكتب). أما
       الدراور المغلق فـvisibility:hidden مع بقاء التخطيط — فيُقاس. */
    if (!r || r.width <= 0 || r.height <= 0) return null;
    return r;
  } catch (e) {
    return null;
  }
}

function reducedMotion() {
  try {
    return !!(window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches);
  } catch (e) {
    return false;
  }
}

/* مرئي فعلاً؟ مقاس حقيقي + لا display:none ولا visibility:hidden
   في أي جدّ — عناصر الدراور المغلق مرفوضة هنا (تُقاس لكنها غير مرئية) */
function isShowing(el) {
  try {
    if (!el || !el.getBoundingClientRect) return false;
    const r = el.getBoundingClientRect();
    if (!r || r.width <= 0 || r.height <= 0) return false;
    let n = el;
    while (n && n.nodeType === 1) {
      let cs = null;
      try {
        cs = window.getComputedStyle(n);
      } catch (e) {
        cs = null;
      }
      if (cs && (cs.display === "none" || cs.visibility === "hidden" || cs.visibility === "collapse")) return false;
      if (n === document.body) break;
      n = n.parentElement;
    }
    return true;
  } catch (e) {
    return false;
  }
}

/* أول هدف عربة له إحداثيات: هيدر (ظاهر) ← شريط الدراور ← زر القائمة */
export function cartTarget() {
  const ids = ["#header #cartBtn", "#cartCountDrawer", "#navToggle"];
  for (let i = 0; i < ids.length; i++) {
    let el = null;
    try {
      el = document.querySelector(ids[i]);
    } catch (e) {}
    if (!el) continue;
    /* الشارة داخل الزر — الهدف هو الزر نفسه لا الشارة */
    const btn = el.closest ? (el.closest("button, a") || el) : el;
    if (rectOf(btn)) return btn;
  }
  return null;
}

/* هدف المفضلة — مرئي فقط دائمًا حتى يُرى الهبوط:
   الدراور مفتوح ← قلب الشريط الحي؛ مغلق ← زر القائمة الظاهر
   (لا نستهدف الدراور المغلق أبدًا: يُقاس لكنه غير مرئي فيُضلَّل) */
export function wishTarget() {
  const drawerOpen = !!(document.body && document.body.classList && document.body.classList.contains("nav-open"));
  const ids = drawerOpen ? ["#wishlistBtnDrawer", "#navToggle"] : ["#navToggle", "#wishlistBtnDrawer"];
  for (let i = 0; i < ids.length; i++) {
    let el = null;
    try {
      el = document.querySelector(ids[i]);
    } catch (e) {}
    if (!el) continue;
    const btn = el.closest ? (el.closest("button, a") || el) : el;
    if (isShowing(btn)) return btn;
  }
  return null;
}

/* صورة المصدر: أقرب بطاقة/صفحة للزر المضغوط */
export function sourceImage(btn) {
  try {
    if (!btn || !btn.closest) return null;
    const scope =
      btn.closest("article.card") ||
      btn.closest(".of-slide") ||
      btn.closest(".pd-main") ||
      btn.closest(".ct-item") ||
      btn.closest("article, li");
    if (!scope || !scope.querySelector) return null;
    /* صورة المنتج — لا أيقونة الزر نفسه */
    const imgs = scope.querySelectorAll("img");
    for (let i = 0; i < imgs.length; i++) {
      const img = imgs[i];
      if (btn.contains && btn.contains(img)) continue;
      if (rectOf(img)) return img;
    }
    return null;
  } catch (e) {
    return null;
  }
}

function pulseEls(list, cls) {
  try {
    (list || []).forEach(function (el) {
      if (!el || !el.classList) return;
      el.classList.remove(cls);
      /* إعادة التشغيل: قراءة إجبارية بين الإزالة والإضافة */
      void el.offsetWidth;
      el.classList.add(cls);
      window.setTimeout(function () {
        try {
          el.classList.remove(cls);
        } catch (e) {}
      }, 650);
    });
  } catch (e) {}
}

function queryAllVisible(sel) {
  const out = [];
  try {
    const nodes = document.querySelectorAll(sel);
    for (let i = 0; i < nodes.length; i++) {
      if (rectOf(nodes[i])) out.push(nodes[i]);
    }
  } catch (e) {}
  return out;
}

/* نبض الشارات بعد الهبوط — العربة بعدّادها، والمفضلة بلا عدّاد.
   ★ R13: المرئي فقط — الدراور المغلق لا يُنبَض (لا يُرى) بل زر القائمة */
export function pulseAfter(kind) {
  try {
    if (kind === "wish") {
      pulseEls(queryAllVisible("#wishlistBtnDrawer, #navToggle"), "is-pop");
      /* تلميح فتح الدراور (جوال): وميض خفيف على «الشطيرة» */
      try {
        const t = document.querySelector("#navToggle");
        if (t && t.classList && isShowing(t)) {
          t.classList.remove("is-hint");
          void t.offsetWidth;
          t.classList.add("is-hint");
          window.setTimeout(function () {
            try {
              t.classList.remove("is-hint");
            } catch (e) {}
          }, 2400);
        }
      } catch (e) {}
      return;
    }
    pulseEls(
      queryAllVisible("#header #cartBtn .tool-badge, #cartCountDrawer, #cartCountToggle"),
      "is-pop"
    );
    /* تلميح فتح الدراور (جوال): وميض خفيف على «الشطيرة» */
    try {
      const t = document.querySelector("#navToggle");
      if (t && t.classList) {
        t.classList.remove("is-hint");
        void t.offsetWidth;
        t.classList.add("is-hint");
        window.setTimeout(function () {
          try {
            t.classList.remove("is-hint");
          } catch (e) {}
        }, 2400);
      }
    } catch (e) {}
  } catch (e) {}
}

/* ★ R13: علامة هبوط مرئية (♥) تثبت أين حطّت البطاقة — تظهر
   لحظة الوصول ثم تتلاشى، حتى لا يُساء فهم نقطة النهاية */
function landMarker(x, y, kind) {
  try {
    const m = document.createElement("div");
    m.className = "atyab-land" + (kind === "wish" ? " is-wish" : "");
    m.setAttribute("aria-hidden", "true");
    m.textContent = kind === "wish" ? "♥" : "●";
    m.style.left = Math.round(x - 15) + "px";
    m.style.top = Math.round(y - 15) + "px";
    document.body.appendChild(m);
    let anim = null;
    try {
      anim = m.animate(
        [
          { transform: "scale(0.4)", opacity: 0 },
          { transform: "scale(1.3)", opacity: 1, offset: 0.35 },
          { transform: "scale(1)", opacity: 1, offset: 0.55 },
          { transform: "scale(0.9)", opacity: 0 }
        ],
        { duration: 650, easing: "ease-out" }
      );
    } catch (e) {
      anim = null;
    }
    const done = function () {
      try {
        m.remove();
      } catch (e) {}
    };
    if (anim && anim.finished && anim.finished.then) anim.finished.then(done, done);
    else window.setTimeout(done, 680);
  } catch (e) {}
}

/* الطيران نفسه: نسخة ثابتة من الصورة → الهدف (تصغير + تلاشي) */
export function flyImageTo(img, targetEl, kind) {
  try {
    if (reducedMotion()) {
      pulseAfter(kind);
      return;
    }
    const r = rectOf(img);
    const t = targetEl ? rectOf(targetEl) : null;
    if (!r) {
      pulseAfter(kind);
      return;
    }
    /* بلا هدف مقاس (سطح مكتب بلا زر مفضلة ظاهر): صعود خفيف وتلاشي */
    if (!t) {
      if (kind === "wish") {
        riseAndFade(r, img);
        return;
      }
      pulseAfter(kind);
      return;
    }
    const size = Math.max(44, Math.min(120, Math.min(r.width, r.height)));
    const ghost = document.createElement("div");
    ghost.className = "atyab-fly" + (kind === "wish" ? " is-wish" : "");
    ghost.setAttribute("aria-hidden", "true");
    const src = img.currentSrc || img.src || "";
    if (src) {
      const pic = document.createElement("img");
      pic.src = src;
      pic.alt = "";
      pic.draggable = false;
      ghost.appendChild(pic);
    }
    if (kind === "wish") {
      const heart = document.createElement("i");
      heart.className = "atyab-fly-heart";
      heart.textContent = "♥";
      ghost.appendChild(heart);
    }
    ghost.style.width = size + "px";
    ghost.style.height = size + "px";
    ghost.style.left = r.left + r.width / 2 - size / 2 + "px";
    ghost.style.top = r.top + r.height / 2 - size / 2 + "px";
    document.body.appendChild(ghost);

    const dx = t.left + t.width / 2 - (r.left + r.width / 2);
    const dy = t.top + t.height / 2 - (r.top + r.height / 2);
    const anim = ghost.animate(
      [
        { transform: "translate(0, 0) scale(1)", opacity: 1 },
        { transform: "translate(" + dx * 0.5 + "px, " + (dy * 0.5 - 46) + "px) scale(0.72)", opacity: 0.96, offset: 0.55 },
        { transform: "translate(" + dx + "px, " + dy + "px) scale(0.16)", opacity: 0.35 }
      ],
      { duration: 680, easing: "cubic-bezier(0.3, 0.7, 0.3, 1)" }
    );
    const done = function () {
      try {
        ghost.remove();
      } catch (e) {}
      /* ★ R13: علامة الهبوط عند نقطة الوصول الحقيقية (للمفضلة) */
      try {
        if (kind === "wish" && t) landMarker(t.left + t.width / 2, t.top + t.height / 2, kind);
      } catch (e) {}
      pulseAfter(kind);
    };
    if (anim && anim.finished && anim.finished.then) anim.finished.then(done, done);
    else window.setTimeout(done, 700);
  } catch (e) {
    try {
      pulseAfter(kind);
    } catch (e2) {}
  }
}

/* بديل المفضلة بلا هدف: القلب يصعد ويتلاشى فوق البطاقة */
function riseAndFade(r, img) {
  try {
    const ghost = document.createElement("div");
    ghost.className = "atyab-fly is-wish";
    ghost.setAttribute("aria-hidden", "true");
    const src = (img && (img.currentSrc || img.src)) || "";
    if (src) {
      const pic = document.createElement("img");
      pic.src = src;
      pic.alt = "";
      ghost.appendChild(pic);
    }
    const heart = document.createElement("i");
    heart.className = "atyab-fly-heart";
    heart.textContent = "♥";
    ghost.appendChild(heart);
    const size = Math.max(44, Math.min(120, Math.min(r.width, r.height)));
    ghost.style.width = size + "px";
    ghost.style.height = size + "px";
    ghost.style.left = r.left + r.width / 2 - size / 2 + "px";
    ghost.style.top = r.top + r.height / 2 - size / 2 + "px";
    document.body.appendChild(ghost);
    const anim = ghost.animate(
      [
        { transform: "translateY(0) scale(1)", opacity: 1 },
        { transform: "translateY(-72px) scale(0.55)", opacity: 0.4 }
      ],
      { duration: 560, easing: "cubic-bezier(0.3, 0.7, 0.3, 1)" }
    );
    const done = function () {
      try {
        ghost.remove();
      } catch (e) {}
      try {
        landMarker(r.left + r.width / 2, r.top + r.height / 2 - 72, "wish");
      } catch (e) {}
      pulseAfter("wish");
    };
    if (anim && anim.finished && anim.finished.then) anim.finished.then(done, done);
    else window.setTimeout(done, 580);
  } catch (e) {
    try {
      pulseAfter("wish");
    } catch (e2) {}
  }
}

/* نقطة الدخول من الأزرار: زر → صورة البطاقة → هدف Kind */
export function flyFromButton(btn, kind) {
  try {
    if (!btn) {
      pulseAfter(kind);
      return;
    }
    const img = sourceImage(btn);
    const target = kind === "wish" ? wishTarget() : cartTarget();
    if (!img) {
      pulseAfter(kind);
      return;
    }
    flyImageTo(img, target, kind);
  } catch (e) {}
}
