/* ============================================================
   أطياب الجاسم (React) — زر المفضلة (Add to favorite)

   يقرأ حالته من Redux (wishlistSlice) — فالقلب في البطاقة وفي صفحة
   المنتج وفي قائمة الأمنيات كلها من مصدر واحد.
     <AddToFavoritesButton id={5} variant="icon" />
   ============================================================ */

import { useCallback } from "react";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { toggleWish } from "../../redux/slices/wishlistSlice.js";
import { uiActions } from "../../redux/slices/uiSlice.js";
import { flyFromButton } from "../../utils/flyToCart.js";
import { Icon } from "../Source/Icons.jsx";

export default function AddToFavoritesButton(props) {
  const dispatch = useAppDispatch();
  const id = Number(props.id);
  const liked = useAppSelector(function (s) {
    return s.wishlist.ids.indexOf(id) !== -1;
  });
  /* اسم المنتج يأتي كـprop (للقراءة فقط) — لا علاقة له بـRedux */
  const productName = props.name || "";

  const onToggle = useCallback(
    function (e) {
      if (e && e.preventDefault) e.preventDefault();
      if (e && e.stopPropagation) e.stopPropagation();
      /* ★ R9: عند الإضافة فقط — البطاقة تطير لقلب المفضلة (بلا عدّاد) */
      if (!liked) {
        try {
          flyFromButton(e && e.currentTarget ? e.currentTarget : null, "wish");
        } catch (err) {}
      }
      dispatch(toggleWish(id));
      dispatch(uiActions.toastShown(liked ? "أُزيل من المفضلة" : "أُضيف إلى المفضلة"));
    },
    [dispatch, id, liked]
  );

  if (props.variant === "tool") {
    return (
      <button
        className={"pd-tool pd-wish" + (liked ? " is-on" : "")}
        type="button"
        data-wish={id}
        aria-pressed={liked ? "true" : "false"}
        onClick={onToggle}
      >
        <Icon name="heart" />
        <span>
          <b>المفضلة</b>
          {liked ? "في قائمة الأمنيات" : "أضف إلى قائمة الأمنيات"}
        </span>
      </button>
    );
  }

  if (props.variant === "mini") {
    /* ★ R17: أيقونة فوق صورة المنتج (هاتف) — بدل الزر العريض */
    return (
      <button
        className={"pd-mini" + (liked ? " is-on" : "")}
        type="button"
        data-wish={id}
        aria-pressed={liked ? "true" : "false"}
        aria-label={liked ? "إزالة " + (productName || "المنتج") + " من المفضلة" : "أضف " + (productName || "المنتج") + " إلى المفضلة"}
        title={liked ? "إزالة من المفضلة" : "أضف إلى المفضلة"}
        onClick={onToggle}
      >
        <Icon name="heart" strokeWidth={1.8} />
      </button>
    );
  }

  return (
    <button
      className={props.className || "wish-btn"}
      type="button"
      data-wish={id}
      aria-pressed={liked ? "true" : "false"}
      aria-label={"إضافة " + (productName || "المنتج") + " إلى المفضلة"}
      title={liked ? "إزالة من المفضلة" : "أضف إلى المفضلة"}
      onClick={onToggle}
    >
      <Icon name="heart" strokeWidth={1.8} />
    </button>
  );
}
