/* ============================================================
   أطياب الجاسم (React) — أزرار المنتج

   يجمع الكومبوننت الوظيفتين في دوال مستقلّة تُستدعى بحسب الطلب، وكلهما
   تأخذ `id` المنتج كـ props وتقرأ بياناتها من Redux (بلا تمرير كائن):

     <ProductButtons id={5} />          ← الزرّان معاً (الأفتراضي)
     <AddToCartButton id={5} qty={2} /> ← يُستدعى في صفحة التفاصيل والعروض
     <ProductDetailsButton id={5} />    ← يفتح ShowProductDetailsPage

   ★ الإضافة للعربة تمرّ عبر thunk في cartSlice (يضيف + يُنبّه) — فلا
     يُكرَّر منطق الرسائل هنا.
   ============================================================ */

import { useCallback, useRef } from "react";
import { Link } from "react-router-dom";
import { productPath } from "../../routes.js";
import { ATYAB_byId } from "../../data/products.js";
import { ATYAB_whatsappBookUrl } from "../../data/appConfig.js";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { selectSupport, digitsOf } from "../../redux/slices/settingsSlice.js";
import { addItem } from "../../redux/slices/cartSlice.js";
import { flyFromButton } from "../../utils/flyToCart.js";
import { isAvailable } from "../../redux/slices/productsFactory.js";
import { Icon } from "../Source/Icons.jsx";

/* دالة: أضف للعربة — id (مطلوب) · qty (اختياري) · children للعنوان
   ★ عند نفاد المنتج (stock صفر · غير متوفر · غير نشط) يتحوّل الزر
     إلى «احجز الآن» برابط واتساب للمالك مع رسالة تلقائية. */
export function AddToCartButton(props) {
  const dispatch = useAppDispatch();
  const support = useAppSelector(selectSupport);
  const product = ATYAB_byId ? ATYAB_byId(Number(props.id)) : null;
  const soldOut = !!product && !isAvailable(product);
  const bookHref = ATYAB_whatsappBookUrl(product, support.whatsappDigits || digitsOf(support.whatsapp));
  const lastTap = useRef(0);

  const onAdd = useCallback(
    function (e) {
      if (soldOut) return;
      /* ★ حارس النقرة المزدوجة: كل ضغطة = قطعة واحدة، والضغطة الثانية
         خلال 800ms تُتجاهل — فالنقر المزدوج اللاإرادي (خصوصاً بالجوال)
         كان يرفع الكمية إلى 2 ويُوهِم أن الزر يضيف مرتين. */
      const at = Date.now();
      if (at - (lastTap.current || 0) < 800) return;
      lastTap.current = at;
      /* ★ R9: طيران البطاقة إلى العربة — يُقرأ قبل إعادة الرسم */
      try {
        flyFromButton(e && e.currentTarget ? e.currentTarget : null, "cart");
      } catch (err) {}
      dispatch(addItem(Number(props.id), Number(props.qty) || 1));
    },
    [dispatch, props.id, props.qty, soldOut]
  );

  /* ★ نافد؟ زر «احجز الآن» يفتح واتساب المالك برسالة جاهزة */
  if (soldOut) {
    return (
      <a
        className={props.className || "btn-cart btn-book"}
        data-cart={props.id}
        href={bookHref}
        target="_blank"
        rel="noopener noreferrer"
        aria-label={props.ariaLabel || "احجز الآن عبر واتساب"}
      >
        <Icon name="whatsapp" strokeWidth={1.9} />
        <span>{props.children || "احجز الآن"}</span>
      </a>
    );
  }

  return (
    <button
      className={props.className || "btn-cart"}
      type="button"
      data-cart={props.id}
      onClick={onAdd}
      aria-label={props.ariaLabel || "أضف للعربة"}
    >
      <Icon name="cart" strokeWidth={1.9} />
      <span>{props.children || "أضف للعربة"}</span>
    </button>
  );
}

/* دالة: عرض تفاصيل المنتج — id فقط (رابط راوتر مباشر) */
export function ProductDetailsButton(props) {
  return (
    <Link className={props.className || "btn-ghost"} to={productPath(props.id)}>
      <span>{props.children || "تفاصيل المنتج"}</span>
      <Icon name="back" strokeWidth={2} />
    </Link>
  );
}

/* الافتراضي: الزرّان معاً */
export default function ProductButtons(props) {
  const product = ATYAB_byId ? ATYAB_byId(Number(props.id)) : null;
  const hasStock = !product || typeof product.stock !== "number" || product.stock > 0;
  return (
    <div className={props.className || "pd-buttons"}>
      <AddToCartButton id={props.id} qty={props.qty} />
      <ProductDetailsButton id={props.id} />
      {hasStock ? null : <span className="pd-out-note">هذا المنتج غير متوفر حالياً</span>}
    </div>
  );
}
